<?php if ( $reminders ) : ?><div class="lw-reminder-alerts"><h2>Pending WhatsApp reminders</h2><?php foreach ( $reminders as $reminder ) : $customer = null; foreach ( $customers as $candidate ) { if ( ( $candidate['id'] ?? '' ) === $reminder['customer_id'] ) { $customer = $candidate; break; } } if ( ! $customer ) continue; $phone = preg_replace( '/\D+/', '', (string) $customer['phone'] ); if ( 8 === strlen( $phone ) ) $phone = '506' . $phone; $wa = 'https://wa.me/' . $phone . '?text=' . rawurlencode( $reminder['message'] ); $customer_link = admin_url( 'admin.php?page=loyalty-wallet&lw_tab=customers#lw-customer-' . rawurlencode( (string) $customer['id'] ) ); ?><div class="lw-reminder-alert"><span class="dashicons dashicons-bell"></span><div><strong><a href="<?php echo esc_url( $customer_link ); ?>"><?php echo esc_html( $customer['name'] ); ?></a></strong><small>Appointment: <?php echo esc_html( $reminder['appointment_date'] ); ?> · WhatsApp reminder ready</small></div><a class="button button-primary" href="<?php echo esc_url( $wa ); ?>" target="_blank" rel="noopener noreferrer">Open WhatsApp</a><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="loyalty_wallet_mark_reminder_sent"><input type="hidden" name="reminder_id" value="<?php echo esc_attr( $reminder['id'] ); ?>"><?php wp_nonce_field( 'loyalty_wallet_mark_reminder_sent' ); ?><button class="button" type="submit">Mark sent</button></form></div><?php endforeach; ?></div><?php endif; ?>
